#include <stdio.h>
typedef struct R { unsigned int lane, checkpoint, watermark, shard; int delta; } R;
typedef struct A { unsigned int checkpoint[4], watermark[4]; int value[4]; } A;
static unsigned int mix(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear(A* a){ for(int i=0;i<4;++i){ a->checkpoint[i]=0u; a->watermark[i]=0u; a->value[i]=0; } }
static void absorb(A* a,const R* r){ unsigned int lane=r->lane%4u; if(r->checkpoint<a->checkpoint[lane]) return; if(r->checkpoint>a->checkpoint[lane]){ a->checkpoint[lane]=r->checkpoint; a->watermark[lane]=r->watermark; a->value[lane]=r->delta; return; } if(r->watermark>a->watermark[lane]){ a->watermark[lane]=r->watermark; a->value[lane]=r->delta; } else if(r->watermark==a->watermark[lane]) a->value[lane]+=r->delta; }
static unsigned int sig(const A* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<4u; ++lane){ h=mix(h,lane+1u); h=mix(h,a->checkpoint[lane]); h=mix(h,a->watermark[lane]); h=mix(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const R canonical_rows[]={{0u,8u,7u,0u,7},{1u,9u,8u,1u,15},{2u,7u,6u,2u,18},{3u,10u,9u,3u,19}}; const R replay_rows[]={{2u,4u,2u,2u,5},{0u,5u,3u,0u,4},{1u,3u,1u,1u,7},{3u,6u,4u,3u,8},{1u,9u,8u,1u,13},{0u,8u,7u,0u,11},{2u,7u,6u,2u,17},{3u,10u,9u,3u,19},{0u,5u,3u,0u,-1},{2u,4u,2u,2u,6},{1u,9u,8u,1u,2},{3u,6u,4u,3u,3},{0u,8u,7u,0u,-4},{2u,7u,6u,2u,1}}; A canonical,replayed,collapsed; clear(&canonical); for(unsigned int i=0u;i<4u;++i) absorb(&canonical,&canonical_rows[i]); clear(&replayed); for(unsigned int i=0u;i<sizeof(replay_rows)/sizeof(replay_rows[0]);++i) absorb(&replayed,&replay_rows[i]); clear(&collapsed); for(unsigned int lane=0u; lane<4u; ++lane){ int merged=0,saw=0; unsigned int checkpoint=0u,watermark=0u; for(unsigned int i=0u;i<sizeof(replay_rows)/sizeof(replay_rows[0]);++i){ const R* row=&replay_rows[i]; if(row->lane%4u!=lane) continue; if(row->checkpoint<checkpoint) continue; if(row->checkpoint>checkpoint){ checkpoint=row->checkpoint; watermark=row->watermark; merged=row->delta; saw=1; continue; } if(row->watermark>watermark){ watermark=row->watermark; merged=row->delta; saw=1; } else if(row->watermark==watermark){ merged+=row->delta; saw=1; } } if(saw){ R row={lane,checkpoint,watermark,lane,merged}; absorb(&collapsed,&row); } } { unsigned int sc=sig(&canonical), sr=sig(&replayed), sx=sig(&collapsed); printf("%u %u %u %u\n", sc, sr, sx, (sc==sr && sc==sx)?1u:0u); } return 0; }
